#pragma once

#include <string>
#include <string_view>

namespace ws::http {
    enum class StatusCode : int {
        OK = 200,
        BadRequest = 400,
        Forbidden = 403,
        NotFound = 404
    };

    enum class Method : int {
        Get = 0,
        Post = 1,
        Put = 2,
        Patch = 3,
        Delete = 4
    };

    inline constexpr std::string_view version { "1.1" };
}

