#include <string>
#include <string_view>
#include "http.h"

namespace ws::http {
    class ConnectionImpl {
    public:
        static void SetRootDirectory(std::filesystem::path dir);
        static std::filesystem::path GetRootDirectory();
        void Close();
        bool Valid() const;
        FileDescriptor Socket() const;
        std::size_t Receive();
        std::size_t Send();
        bool KeepAlive() const;
        bool Process();

    protected:
        FileDescriptor socket_;
        bool keep_alive_;
        IOBuffer read_buf_;
        IOBuffer write_buf_;
        MappedReadOnlyFile file_;
        static std::filesystem::path root_dir_;
    };

    class Connection : public ConnectionImpl {
    public:
        IPAddr addr_;
        IPAddress();
        Port();
    };
}

#pragma once

#include <filesystem>
#include <optional>
#include <string>
#include <string_view>
#include <unordered_map>
#include "http.h"

namespace ws::http {
    using Parameters = std::unordered_map<std::string, std::string>;

    class Request {
    public:
        void Parse(Buffer& buf);
        std::optional<std::string_view> Header(std::string_view key) const;
        std::optional<std::string_view> Post(std::string_view key) const;
        std::size_t PostSize() const;
        Method Method() const;
        std::string_view Path() const;
        std::string_view Version() const;
        bool KeepAlive() const;

    private:
        class State;
        State* state_;
        Method method_;
        std::string version_;
        std::string path_;
        Parameters headers_;
        Parameters post_;
    };
}

#include "request.h"

namespace ws::http {
    class Request::State {
    public:
        virtual ~State() = default;
        virtual void Parse(Request& req, Buffer& buf) = 0;
    };

    class NotStarted : public State {
    public:
        void Parse(Request& req, Buffer& buf) override;
    };

    class Header : public State {
    public:
        void Parse(Request& req, Buffer& buf) override;
    };

    class Body : public State {
    public:
        void Parse(Request& req, Buffer& buf) override;
    };

    class Finished : public State {
    public:
        void Parse(Request& req, Buffer& buf) override;
    };
}

